import { announce, definePrimitive } from "@ui-sdk/core"

import { unavailable } from "@/lib/action-refusal"

type DeviceCodePromptOptions = {
  /** The page where the person enters the code. Kept out of the state while `agentHidden`. */
  verificationUri?: string
  /** The same page with the code filled in; `open` prefers it. */
  verificationUriComplete?: string
  /** Hides the link from agents: it stays out of the state, and `open` and `copyLink` refuse an agent's call. */
  agentHidden?: boolean
  /** Runs after the provider's page opened in a new tab, with the address it opened. */
  onOpen?: (uri: string) => void
  /** Runs after the link reached the clipboard. */
  onCopyLink?: (uri: string) => void
  /** Runs once, when the code expires. */
  onExpire?: () => void
  linkCopiedAnnouncement?: string
  expiredAnnouncement?: string
}

type DeviceCodePromptState = {
  /** The verification page; absent while it's hidden from agents. */
  verificationUri?: string
  linkCopied: boolean
  expired: boolean
}

const COPIED_FOR_MS = 2000

const hiddenFromAgents = "the code and its link are hidden from agents, so a person opens them"

const visibleUri = (options: DeviceCodePromptOptions) =>
  options.agentHidden ? undefined : (options.verificationUri ?? "")

const deviceCodePrompt = definePrimitive({
  name: "device-code-prompt",
  options: {
    verificationUri: "string",
    verificationUriComplete: "string",
    agentHidden: "boolean",
    onOpen: "callback",
    onCopyLink: "callback",
    onExpire: "callback",
    linkCopiedAnnouncement: "string",
    expiredAnnouncement: "string",
  },
  controlled: ["verificationUri", "linkCopied", "expired"],
  state: (options: DeviceCodePromptOptions): DeviceCodePromptState => {
    const verificationUri = visibleUri(options)
    return { ...(verificationUri === undefined ? {} : { verificationUri }), linkCopied: false, expired: false }
  },
  sync: (options) => ({ verificationUri: visibleUri(options) }),
  api: (context) => {
    let copiedTimer: ReturnType<typeof setTimeout> | undefined
    context.onDestroy(() => clearTimeout(copiedTimer))
    const hiddenFromThisCall = (event: Event | undefined) => context.options().agentHidden === true && !event

    const refusal = (action: string, event: Event | undefined) => {
      const call = { event }
      if (hiddenFromThisCall(event)) return unavailable(action, `isn't available: ${hiddenFromAgents}`, call)
      if (context.store.get().expired) return unavailable(action, "isn't available: the code has expired", call)
      if (!context.options().verificationUri) return unavailable(action, "isn't available: there is no link", call)
      return null
    }

    return {
      /** Opens the provider's page in a new tab, with the code filled in when `verificationUriComplete` is set. */
      open(event?: Event) {
        const refused = refusal("open", event)
        if (refused !== null) return refused
        const options = context.options()
        const uri = options.verificationUriComplete ?? options.verificationUri ?? ""
        if (typeof window === "undefined") return unavailable("open", "isn't available outside a browser", { event })
        window.open(uri, "_blank", "noopener,noreferrer")
        options.onOpen?.(uri)
        return true
      },
      /** Writes the verification page's address to the clipboard. Resolves to `"copied"`. */
      copyLink(event?: Event): Promise<"copied" | false> | false {
        const refused = refusal("copyLink", event)
        if (refused !== null) return refused
        const uri = context.options().verificationUri ?? ""
        const call = { event }
        const clipboard = typeof navigator === "undefined" ? undefined : navigator.clipboard
        if (!clipboard) return unavailable("copyLink", "isn't available: the page has no clipboard access", call)
        return clipboard.writeText(uri).then(
          () => {
            clearTimeout(copiedTimer)
            context.store.set({ linkCopied: true })
            copiedTimer = setTimeout(() => context.store.set({ linkCopied: false }), COPIED_FOR_MS)
            const { linkCopiedAnnouncement, onCopyLink } = context.options()
            if (linkCopiedAnnouncement) announce(linkCopiedAnnouncement)
            onCopyLink?.(uri)
            return "copied" as const
          },
          () => unavailable("copyLink", "was blocked by the browser", call),
        )
      },
      /** Marks the code expired, once: opening stops, `onExpire` runs and the expiry is announced. */
      expire() {
        if (context.store.get().expired) return
        context.store.set({ expired: true })
        const { onExpire, expiredAnnouncement } = context.options()
        if (expiredAnnouncement) announce(expiredAnnouncement)
        onExpire?.()
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, DeviceCodePromptState>({
      state: (state) => ({ ...state }),
      attrs: (state) => ({
        role: "group",
        "data-expired": state.expired ? "" : undefined,
        "data-link-copied": state.linkCopied ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["open", "copyLink"] },
})

export { deviceCodePrompt }
export type { DeviceCodePromptOptions, DeviceCodePromptState }

"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { CheckIcon, ClockAlertIcon, CopyIcon, ExternalLinkIcon } from "lucide-react"
import type { ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { deviceCodePrompt, type DeviceCodePromptState } from "@/components/ui/device-code-prompt-primitive"
import { ExpiryCountdown, type ExpiresInText } from "@/components/ui/expiry-countdown"
import { Link } from "@/components/ui/link"
import { PairingCode, type PairingCodeLabels, type PairingCodeSize } from "@/components/ui/pairing-code"
import { useExpiry } from "@/components/ui/use-expiry"
import { cn } from "@/lib/utils"

/** The prompt's visible text. None has a default: pass it in the page's language. */
type DeviceCodePromptText = {
  /** The sentence around the link to the provider's page: (link) => <>Go to {link} and enter this code.</> */
  instructions: (link: ReactNode) => ReactNode
  /** The button that opens the provider's page in a new tab. */
  open: ReactNode
  /** The time left, shown each second and read once a minute, then at 30, 20 and 10 seconds. */
  expiresIn?: ExpiresInText
  /** Shown, and read, once `expiresAt` passes; the code, the link and Open go away, `actions` stay. */
  expired?: string
}

/** Names and announcements for screen readers and agents; English by default. */
type DeviceCodePromptLabels = {
  prompt: string
  code: string
  copyLink: string
  linkCopied: string
  linkCopiedAnnouncement: string
  /** Read after the link, which opens in a new tab. */
  newTab: string
  /** The code's own copy button and spelling. */
  pairingCode?: Partial<PairingCodeLabels>
}

const deviceCodePromptLabels: DeviceCodePromptLabels = {
  prompt: "Sign-in code",
  code: "Code",
  copyLink: "Copy link",
  linkCopied: "Copied",
  linkCopiedAnnouncement: "Link copied",
  newTab: "(opens in a new tab)",
}

type DeviceCodePromptProps = {
  /** The user code from the provider, with or without separators, in any case. */
  code: string
  /** The provider's page where the person enters the code. */
  verificationUri: string
  /** The same page with the code filled in; Open uses it when given. */
  verificationUriComplete?: string
  /** Characters per visual group; 4 by default. */
  groupSize?: number
  /** Shown between groups and copied with the code; "-" by default. */
  separator?: string
  size?: PairingCodeSize
  /** Adds a button that copies the verification page's address. */
  copyLink?: boolean
  /** When the code expires, as a Date or epoch milliseconds. */
  expiresAt?: Date | number
  /** Runs once, when `expiresAt` passes. */
  onExpire?: () => void
  /** Runs after Open, with the address it opened. */
  onOpen?: (uri: string) => void
  /** Runs once the code, with separators, is on the clipboard. */
  onCopy?: (code: string) => void
  onCopyLink?: (uri: string) => void
  /**
   * Keeps the code and the link from agents: they stay out of the snapshot and queries, and `open`, `copyLink` and
   * the code's `copy` fail an agent's step with why. On by default, since the code signs an account in.
   */
  agentHidden?: boolean
  /** More controls after Open, like a Cancel that abandons the sign-in; they stay once the code expires. */
  actions?: ReactNode
  text: DeviceCodePromptText
  labels?: Partial<DeviceCodePromptLabels>
  /** Names the prompt for screen readers and agents; `labels.prompt` by default. */
  "aria-label"?: string
  className?: string
}

const rootAttributes: Record<`data-${string}`, string> = { "data-slot": "device-code-prompt" }

const scheme = /^https?:\/\//i
const trailingSlash = /\/$/

const withoutScheme = (uri: string) => uri.replace(scheme, "").replace(trailingSlash, "")

const actionsClassName = "flex flex-wrap items-center gap-items narrow:flex-col narrow:items-stretch"

const ignoreRefusal = () => undefined

function DeviceCodePrompt({
  code,
  verificationUri,
  verificationUriComplete,
  groupSize,
  separator,
  size,
  copyLink = false,
  expiresAt,
  onExpire,
  onOpen,
  onCopy,
  onCopyLink,
  agentHidden = true,
  actions,
  text,
  labels: overrides,
  "aria-label": label,
  className,
}: DeviceCodePromptProps) {
  const labels = { ...deviceCodePromptLabels, ...overrides }
  const handle = usePrimitive(deviceCodePrompt, {
    verificationUri,
    verificationUriComplete,
    agentHidden,
    onOpen,
    onCopyLink,
    onExpire,
    linkCopiedAnnouncement: labels.linkCopiedAnnouncement,
    expiredAnnouncement: text.expired,
  })
  const { api } = handle
  const expiry = expiresAt instanceof Date ? expiresAt.getTime() : expiresAt
  useExpiry(expiry, () => api.expire())
  const hidden = agentHidden ? "" : undefined

  return usePart(
    handle,
    "root",
    {},
    {
      ...rootAttributes,
      "aria-label": label ?? labels.prompt,
      className: cn("flex min-w-0 flex-col gap-items", className),
      children: (state: DeviceCodePromptState) =>
        state.expired ? (
          <>
            <p
              data-slot="device-code-prompt-expired"
              className="flex items-center gap-inline text-body-sm font-medium text-warning-soft-foreground [&_svg]:size-4"
            >
              <ClockAlertIcon />
              {text.expired}
            </p>
            {actions === undefined || actions === null ? null : (
              <div data-slot="device-code-prompt-actions" className={actionsClassName}>
                {actions}
              </div>
            )}
          </>
        ) : (
          <>
            <p data-slot="device-code-prompt-instructions" className="text-body text-muted-foreground">
              {text.instructions(
                <span
                  data-slot="device-code-prompt-link"
                  data-agent-hidden={hidden}
                  className="inline-flex max-w-full items-center gap-inline align-middle"
                >
                  <Link
                    href={verificationUri}
                    external
                    newTab
                    newTabLabel={labels.newTab}
                    fast={false}
                    translate="no"
                    className="min-w-0 font-medium break-all"
                  >
                    {withoutScheme(verificationUri)}
                  </Link>
                  {copyLink ? (
                    <Button
                      size="icon"
                      variant="ghost"
                      className="size-control-sm shrink-0 text-muted-foreground"
                      aria-label={state.linkCopied ? labels.linkCopied : labels.copyLink}
                      onClick={(event) => {
                        const copied = api.copyLink(event.nativeEvent)
                        if (copied) copied.then(undefined, ignoreRefusal)
                      }}
                    >
                      {state.linkCopied ? <CheckIcon /> : <CopyIcon />}
                    </Button>
                  ) : null}
                </span>,
              )}
            </p>
            <PairingCode
              code={code}
              label={labels.code}
              groupSize={groupSize}
              separator={separator}
              size={size}
              agentHidden={agentHidden}
              onCopy={onCopy}
              labels={labels.pairingCode}
            />
            {expiry !== undefined && text.expiresIn ? (
              <ExpiryCountdown data-slot="device-code-prompt-countdown" expiresAt={expiry} expiresIn={text.expiresIn} />
            ) : null}
            <div data-slot="device-code-prompt-actions" className={actionsClassName}>
              <span data-agent-hidden={hidden} className="contents">
                <Button className="narrow:w-full" onClick={(event) => api.open(event.nativeEvent)}>
                  <ExternalLinkIcon />
                  {text.open}
                </Button>
              </span>
              {actions}
            </div>
          </>
        ),
    },
  )
}

export { DeviceCodePrompt, deviceCodePromptLabels }
export type { DeviceCodePromptLabels, DeviceCodePromptProps, DeviceCodePromptText }
